function getPublicSwalBase(){const isLight=document.documentElement.getAttribute('data-public-mode')==='light'||(typeof getPublicAppearanceMode==='function'&&getPublicAppearanceMode()==='light');if(isLight){return{background:'#FFFFFF',backdrop:'rgba(15, 23, 42, 0.45)',color:'#0F172A',cancelButtonColor:'#CBD5E1'};}
return{background:'#0a0a14',backdrop:'rgba(0,0,0,0.75)',color:'var(--color-text)',cancelButtonColor:'#1f2436'};}
async function clearAllCart(){const cart=getCart();if(!cart.length)return;const base=getPublicSwalBase();const{isConfirmed}=await Swal.fire({...base,icon:'warning',title:'حذف كل السلة؟',text:`هيتم حذف ${cart.length} عنصر من السلة نهائياً!`,showCancelButton:true,confirmButtonText:'<i class="fa-solid fa-trash me-1"></i> نعم، احذف الكل',cancelButtonText:'إلغاء',customClass:{popup:'storage-popup',confirmButton:'storage-confirm danger',cancelButton:'storage-cancel'}});if(isConfirmed){saveCart([]);updateCartUI();}}
async function clearTypeCart(type){const cart=getCart();const items=type==='game'?cart.filter(i=>i.type==='game'||!i.type):cart.filter(i=>i.type===type);if(!items.length)return;const labels={game:'الألعاب',movie:'الأفلام والمسلسلات',program:'البرامج',electronics:'الإلكترونيات'};const label=labels[type]||'المنتجات';const base=getPublicSwalBase();const{isConfirmed}=await Swal.fire({...base,icon:'warning',title:`حذف كل ${label}؟`,text:`هيتم حذف ${items.length} عنصر نهائياً!`,showCancelButton:true,confirmButtonText:'<i class="fa-solid fa-trash me-1"></i> نعم، احذف',cancelButtonText:'إلغاء',customClass:{popup:'storage-popup',confirmButton:'storage-confirm danger',cancelButton:'storage-cancel'}});if(isConfirmed){const newCart=type==='game'?cart.filter(i=>i.type==='movie'||i.type==='electronics'):cart.filter(i=>i.type!==type);saveCart(newCart);updateCartUI();}}
