function ensurePublicAppearanceFab(){if(document.getElementById('fabAppearance'))return;if(!document.body)return;if(document.body.classList.contains('admin-page')||document.body.classList.contains('admin-body'))return;const btn=document.createElement('button');btn.type='button';btn.className='fab-btn fab-appearance';btn.id='fabAppearance';btn.title='مظهر الموقع: داكن (Dark)';btn.setAttribute('aria-label','مظهر الموقع: داكن (Dark)');btn.innerHTML='<i class="fa-solid fa-moon" id="fabAppearanceIcon"></i>';btn.addEventListener('click',cyclePublicAppearance);const wrap=document.createElement('div');wrap.className='floating-actions';wrap.id='injectedFloatingActions';wrap.appendChild(btn);document.body.appendChild(wrap);}
function updatePublicAppearanceUI(){const mode=getPublicAppearanceMode();document.documentElement.setAttribute('data-public-mode',mode);const btn=document.getElementById('fabAppearance');const icon=document.getElementById('fabAppearanceIcon');if(btn&&icon){let label='مظهر داكن (Dark mode)';if(mode==='light'){icon.className='fa-solid fa-sun';label='مظهر فاتح (Light mode)';}else{icon.className='fa-solid fa-moon';label='مظهر داكن (Dark mode)';}
btn.title=label;btn.setAttribute('aria-label',label);}}
function cyclePublicAppearance(){const current=getPublicAppearanceMode();const next=current==='dark'?'light':'dark';localStorage.setItem('pgPublicAppearance',next);updatePublicAppearanceUI();const label=next==='light'?'فاتح (Light)':'داكن (Dark)';if(typeof showToast==='function'){showToast('info','تم تغيير مظهر الموقع إلى: '+label);}}
window.getPublicAppearanceMode=getPublicAppearanceMode;window.updatePublicAppearanceUI=updatePublicAppearanceUI;window.cyclePublicAppearance=cyclePublicAppearance;function initAppearanceUi(){ensurePublicAppearanceFab();updatePublicAppearanceUI();}
